package android.widget;
public class CheckedTextView extends TextView implements Checkable { private boolean checked; private android.graphics.drawable.Drawable mark; public CheckedTextView(android.content.Context c) { super(c); } public CheckedTextView(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public CheckedTextView(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public CheckedTextView(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } public void setChecked(boolean b) { checked=b; invalidate(); } public boolean isChecked() { return checked; } public void toggle() { setChecked(!checked); } public void setCheckMarkDrawable(android.graphics.drawable.Drawable d) { mark=d; } public void setCheckMarkDrawable(int id) { mark=id==0?null:getResources().getDrawable(id); } public android.graphics.drawable.Drawable getCheckMarkDrawable() { return mark; }  public void setCheckMarkTintList(android.content.res.ColorStateList tint) {} public void setCheckMarkTintMode(android.graphics.PorterDuff.Mode mode) {}
}
